import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const accent = colors.accent ?? '#ff2a38';
  const surface = colors.surface ?? '#0b0b10';

  const primitiveHandles = [];
  for (const p of config.cinematicPrimitives ?? []) {
    if (ctx.primitives?.[p.name]) {
      primitiveHandles.push(ctx.primitives[p.name](root, p.params ?? {}));
    }
  }

  const panelW = 7.0;
  const panelH = 1.6;
  const geometry = new PlaneGeometry(panelW, panelH);

  const u = uv();
  const gradT = smoothstep(0.0, 1.0, u.y);
  const grad = mix(color(surface), color(ink), gradT);

  const grain =
    fract(sin(u.x.mul(1234.0).add(u.y.mul(4321.0))).mul(43758.5453))
      .sub(0.5)
      .mul(0.025);

  const accentLine = smoothstep(0.0, 0.025, u.y).sub(smoothstep(0.025, 0.05, u.y));
  const gradGrain = grad.add(grain);
  const finalColor = mix(gradGrain, color(accent), accentLine.mul(0.85));

  const material = new MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  const panel = new Mesh(geometry, material);
  panel.position.z = -0.05;
  root.add(panel);

  const timelines = [];
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  for (const item of items) {
    if (!item?.text) continue;

    const fontSize = item.typography?.fontSize ?? 96;
    const textNode = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: paper,
      align: 'center',
    });

    textNode.position.z = 0.05;

    const endY = textNode.position.y;
    textNode.position.y -= 0.2;

    const tl = gsap.timeline({ delay: 0.1 });
    tl.to(textNode.position, { y: endY, duration: 0.7, ease: 'power3.out' });
    tl.from(textNode.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.7, ease: 'power4.out' }, 0);
    timelines.push(tl);

    root.add(textNode);
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primitiveHandles.forEach((h) => h?.cleanup?.());

    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
